{
  "patch": {
    "summary": "Replace foreground server launch with bounded service test using mobyai-service-check",
    "rationale_summary": "The previous validation used a foreground server process that couldn't exit, violating harness constraints. This patch replaces it with a finite service test that starts the server, verifies healthz endpoint, observes for 30s, then terminates. The health check endpoint (/healthz) must return 200 OK within 10s startup window.",
    "supersede": [
      {
        "task_id": "STEP_003A_FIX_V2_REPAIR_3",
        "replacements": [
          {
            "task_id": "STEP_003A_FIX_V2_REPAIR_3A",
            "name": "Validate server startup with health check",
            "description": "Run Uvicorn server through mobyai-service-check with healthz endpoint verification",
            "target_files": ["backend/app.py"],
            "required_context": [],
            "dependencies": ["STEP_001B", "STEP_002A"],
            "acceptance_criteria": [
              "Server starts within 10s and responds to /healthz with 200 OK",
              "Server remains responsive for full 30s observation period",
              "Process terminates cleanly after observation completes"
            ],
            "test_commands": [
              "mobyai-service-check --url http://127.0.0.1:8000/healthz --startup-seconds 10 --observe-seconds 30 -- .venv/bin/python -m uvicorn backend.app:app --host 0.0.0.0 --port 8000"
            ]
          }
        ]
      }
    ],
    "add_tasks": []
  }
}
